# Let's re-run BFS more carefully and also check if there are nodes reachable 
# through different paths that might be at depth 4

# Actually, let me verify by also checking what nodes are reachable at exactly depth 4
# using a different approach - track all paths up to depth 4

def bfs_all_nodes_at_exact_depth(start, graph, target_depth):
    """Find all nodes at exactly target_depth using BFS"""
    # Use a dict to track the shortest distance to each node
    distance = {start: 0}
    queue = deque([start])

    while queue:
        node = queue.popleft()
        current_dist = distance[node]
        if current_dist >= target_depth:
            continue
        for neighbor in graph.get(node, []):
            if neighbor not in distance:
                distance[neighbor] = current_dist + 1
                queue.append(neighbor)

    # Return nodes at exactly target_depth
    result = [node for node, dist in distance.items() if dist == target_depth]
    return sorted(result)

